	('L00178', 'history_scope.wireless_audio', 'Sạc không dây, tai nghe Bluetooth', 'Wireless charger, Bluetooth headset', '무선 충전기, 블루투스 이어폰', '2026-05-13 19:08:43', 'Cườngg'),
	('L00179', 'history_scope_desc', 'Partron Vina là nhà cung cấp vệ tinh hàng đầu của Samsung Electronics Việt Nam, đồng thời sản xuất linh kiện cho các hãng lớn như Amazon. Sản phẩm đã có mặt tại Hàn Quốc, EU, Brazil, Ấn Độ...', 'Partron Vina is a leading satellite supplier of Samsung Electronics Vietnam and also manufactures components for major brands like Amazon. Products are available in Korea, EU, Brazil, India...', '파트론비나는 삼성전자 베트남의 주요 협력업체이며, Amazon 등 글로벌 기업에 부품을 공급합니다. 제품은 한국, EU, 브라질, 인도 등지에 유통되었습니다', '2026-05-19 07:58:44', 'Cườngg'),
