	('L00396', 'validate_auction.image_url_min', 'Phải chọn ít nhất 1 ảnh', 'Must select at least 1 images', '최소 1장의 사진을 선택해야 합니다.', '2026-05-13 19:08:43', 'Cườngg'),
	('L00397', 'validate_auction.participants_required', 'Người tham gia là bắt buộc', 'Participants are required', '참가자는 필수 항목입니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00398', 'validate_auction.starting_price_min', 'Giá khởi điểm phải lớn hơn 0', 'Starting price must be > 0', '시작가는 0보다 커야 합니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00399', 'validate_auction.step_price_min', 'Bước giá phải > 0', 'Price step must be > 0', '단가는 0보다 커야 합니다.', '2026-05-13 19:08:43', 'Cườngg'),
	('L00400', 'validate_auction.title_max', 'Tiêu đề không được vượt quá 200 ký tự', 'Title must not exceed 200 characters', '제목은 200자를 초과할 수 없습니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00401', 'validate_auction.title_required', 'Tiêu đề là bắt buộc', 'Title is required', '제목은 필수 항목입니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00402', 'validate_bid.address_max', 'Địa chỉ không được vượt quá 100 ký tự', 'Address cannot exceed 100 characters', '주소는 100자를 초과할 수 없습니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00403', 'validate_bid.address_required', 'Địa chỉ là bắt buộc', 'Address is required', '주소는 필수 항목입니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00404', 'validate_bid.bid_amount_decimal', 'Chỉ cho phép tối đa 2 chữ số thập phân', 'Only allow up to 2 decimal places', '소수점 둘째 자리까지만 허용됩니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00405', 'validate_bid.bid_amount_positive', 'Giá trị phải lớn hơn 0', 'Value must be greater than 0', '값은 0보다 커야 합니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00406', 'validate_bid.note_max', 'Ghi chú không được vượt quá 1000 ký tự.', 'Notes must not exceed 1000 characters.', '메모는 1000자를 초과할 수 없습니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00407', 'vi_col', 'VI', 'VI', 'VI', '2026-05-13 19:08:43', 'Cườngg'),
	('L00408', 'view', 'Xem', 'View', '보기', '2026-05-13 19:08:43', 'Cườngg'),
	('L00409', 'view_all_auction', 'Xem tất cả phiên đấu giá', 'View All Auction', '모든 입찰 보기', '2026-05-13 19:08:43', 'Cườngg'),
	('L00410', 'view_auction_detail', 'Xem đấu giá', 'View Auction', '입찰 보기', '2026-05-13 19:08:43', 'Cườngg'),
	('L00411', 'vision_p1', 'Với vị thế là một trong những doanh nghiệp hàng đầu trong lĩnh vực sản xuất linh kiện điện tử tại Việt Nam, Công ty TNHH Partron Vina luôn không ngừng đổi mới và tiên phong trong việc áp dụng công nghệ vào hoạt động kinh doanh. Việc triển khai nền tảng đấu giá trực tuyến không chỉ là bước tiến trong việc đa dạng hóa kênh phân phối sản phẩm mà còn thể hiện cam kết của công ty trong việc nâng cao trải nghiệm khách hàng và tối ưu hóa giá trị sản phẩm.', 'As one of the leading companies in the field of electronic component manufacturing in Vietnam, Partron Vina Co., Ltd. continuously innovates and pioneers in applying technology to its business operations. The implementation of the online auction platform is not only a step forward in diversifying product distribution channels but also a demonstration of the company’s commitment to enhancing customer experience and optimizing product value.', '베트남 전자부품 제조 분야의 선도 기업 중 하나인 파트론 비나 유한회사는 끊임없는 혁신을 통해 기술을 비즈니스 운영에 적극적으로 적용하고 있습니다. 온라인 입찰 웹사이트의 도입은 제품 유통 채널을 다양화하는 것뿐만 아니라 고객 경험을 향상시키고 제품 가치를 최적화하려는 회사의 의지를 보여줍니다.', '2026-05-19 07:58:44', 'Cườngg'),
	('L00412', 'vision_p2', 'Thông qua nền tảng này, Partron Vina hướng đến việc tạo ra một môi trường giao dịch minh bạch, công bằng và hiệu quả, đồng thời mở rộng cơ hội tiếp cận sản phẩm đến nhiều đối tượng khách hàng hơn.', 'Through this platform, Partron Vina aims to create a transparent, fair, and efficient trading environment while expanding access to its products for a broader range of customers.', '이 웹사이트 통해 파트론 비나는 투명하고 공정하며 효율적인 거래 환경을 구축하고, 더 많은 고객이 제품에 접근할 수 있는 기회를 확대하고자 합니다', '2026-05-19 07:58:44', 'Cườngg'),
	('L00413', 'vision_p3', 'Thông qua việc triển khai nền tảng đấu giá trực tuyến, Partron Vina không chỉ khẳng định vị thế tiên phong trong lĩnh vực công nghệ mà còn thể hiện cam kết mạnh mẽ trong việc mang lại giá trị tối ưu cho khách hàng và đối tác.', 'By launching the online auction platform, Partron Vina not only affirms its pioneering position in the field of technology but also demonstrates a strong commitment to delivering optimal value to customers and partners.', '온라인 입찰 플랫폼의 도입을 통해 파트론 비나는 기술 분야에서의 선도적 위치를 다시 한 번 확고히 하는 동시에 고객과 파트너에게 최적의 가치를 제공하겠다는 강한 의지를 나타내고 있습니다.', '2026-05-19 07:58:44', 'Cườngg'),
	('L00414', 'vision_title', 'Tầm nhìn và định hướng phát triển', 'Vision & Development Orientation', '비전 및 발전 방향', '2026-05-13 19:08:43', 'Cườngg'),
	('L00415', 'void_bid', 'Hủy lượt đấu giá', 'Void Bid', '입찰 취소', '2026-05-13 19:08:43', 'Cườngg'),
	('L00416', 'void_bid_acknowledge', 'Tôi đã hiểu', 'I Understand', '확인했습니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00417', 'void_bid_confirm', 'Bạn có chắc chắn muốn hủy lượt đấu giá của', 'Are you sure you want to void the bid from', '다음 사용자의 입찰을 취소하시겠습니까?', '2026-05-19 07:58:44', 'Cườngg'),
	('L00418', 'void_bid_warning_count', '{{count}} lượt đấu giá đã bị hủy', '{{count}} bid(s) have been voided', '{{count}}건의 입찰이 취소되었습니다', '2026-05-19 07:58:44', 'Cườngg'),
	('L00419', 'void_bid_warning_single', 'Đấu giá của bạn đã bị vô hiệu hóa', 'Your bid has been invalidated', '귀하의 입찰이 무효 처리되었습니다', '2026-05-13 19:08:43', 'Cườngg'),
	('L00420', 'void_bid_warning_title', 'Đấu giá bị hủy bởi Quản trị viên', 'Bid Voided by Administrator', '관리자에서 해당 입찰 무효화 처리하었습니다', '2026-05-19 07:58:44', 'Cườngg'),
	('L00421', 'winner', 'Người thắng', 'Winner', '낙찰자', '2026-05-19 07:58:44', 'Cườngg'),
